resource aks 'Microsoft.ContainerService/managedClusters@2024-05-01' = {
  name: aksName
  location: location
  tags: tags
  sku: {
    name: 'Base'
    tier: 'Paid'
  }
  identity: {
    type: 'SystemAssigned'
  }
  properties: {
    kubernetesVersion: kubernetesVersion == '' ? null : kubernetesVersion
    dnsPrefix: toLower('${aksName}-dns')
    nodeResourceGroup: nodeResourceGroupName
    enableRBAC: true
    disableLocalAccounts: true
    aadProfile: {
      managed: true
      enableAzureRBAC: true
      adminGroupObjectIDs: aadAdminGroupObjectIds
    }
    apiServerAccessProfile: {
      enablePrivateCluster: enablePrivateCluster
      enablePrivateClusterPublicFQDN: false
      privateDNSZone: enablePrivateCluster ? 'System' : null
      authorizedIPRanges: enablePrivateCluster ? null : authorizedIPRanges
    }
    autoScalerProfile: {
      balanceSimilarNodeGroups: 'true'
      expander: 'least-waste'
      maxEmptyBulkDelete: '10'
      maxGracefulTerminationSec: '600'
      maxTotalUnreadyPercentage: '45'
      okTotalUnreadyCount: '3'
      scanInterval: '20s'
      scaleDownDelayAfterAdd: '15m'
      scaleDownDelayAfterDelete: '15s'
      scaleDownDelayAfterFailure: '10m'
      scaleDownUnneededTime: '10m'
      scaleDownUnreadyTime: '20m'
      scaleDownUtilizationThreshold: '0.5'
      skipNodesWithLocalStorage: 'false'
      skipNodesWithSystemPods: 'false'
      newPodScaleUpDelay: '0s'
    }
    autoUpgradeProfile: {
      upgradeChannel: 'stable'
    }
    oidcIssuerProfile: {
      enabled: true
    }
    securityProfile: {
      workloadIdentity: {
        enabled: true
      }
      imageCleaner: {
        enabled: true
        intervalHours: 48
      }
    }
    addonProfiles: {
      azurepolicy: {
        enabled: true
      }
      omsagent: {
        enabled: true
        config: {
          logAnalyticsWorkspaceResourceID: law.id
        }
      }
      azureKeyvaultSecretsProvider: {
        enabled: true
        config: {
          enableSecretRotation: 'true'
          rotationPollInterval: '2m'
        }
      }
    }
    networkProfile: {
      networkPlugin: 'azure'
      networkPluginMode: 'overlay'
      networkPolicy: 'azure'
      serviceCidr: serviceCidr
      dnsServiceIP: dnsServiceIP
      podCidrs: [
        podCidr
      ]
      loadBalancerSku: 'standard'
      outboundType: 'managedNATGateway'
      natGatewayProfile: {
        managedOutboundIPProfile: {
          count: outboundIpCount
        }
      }
      ipFamilies: [
        'IPv4'
      ]
      vnetSubnetID: subnetId
    }
    agentPoolProfiles: [
      {
        name: 'systempool'
        mode: 'System'
        count: systemMinCount
        enableAutoScaling: true
        minCount: systemMinCount
        maxCount: systemMaxCount
        vmSize: systemNodeVMSize
        osType: 'Linux'
        type: 'VirtualMachineScaleSets'
        osDiskType: 'Managed'
        osDiskSizeGB: systemOsDiskSizeGB
        availabilityZones: zones
        enableNodePublicIP: false
        nodeTaints: [
          'CriticalAddonsOnly=true:NoSchedule'
        ]
        nodeLabels: {
          'nodepool-type': 'system'
          'workload': 'system'
        }
        scaleSetPriority: 'Regular'
        upgradeSettings: {
          maxSurge: '33%'
        }
        enableEncryptionAtHost: enableEncryptionAtHost
        orchestratorVersion: kubernetesVersion == '' ? null : kubernetesVersion
      }
    ]
  }
}

